'use strict';

/** A user-facing failure: the CLI prints its message and exits with status 1. */
class TodoError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = 'TodoError';
  }
}

const DIGITS = /^\d+$/;

/**
 * Parses a CLI id argument. Accepts only ASCII digits so that "1.5", "-1",
 * "1e2", "0x1" and " 1" are rejected instead of being coerced by Number().
 */
function parseId(raw) {
  const id = DIGITS.test(raw) ? Number(raw) : NaN;
  if (!Number.isSafeInteger(id) || id < 1) {
    throw new TodoError(`Invalid todo id "${raw}". Expected a positive integer such as 1.`);
  }
  return id;
}

function nextId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
}

function findTodo(todos, id) {
  const todo = todos.find((candidate) => candidate.id === id);
  if (!todo) {
    throw new TodoError(`No todo with id ${id}. Run "node index.js list" to see existing ids.`);
  }
  return todo;
}

/**
 * Returns a new list with the todo appended; the input list is not modified.
 * Whitespace runs (including newlines) collapse to one space so each todo
 * stays on a single line in `list` output.
 */
function addTodo(todos, text, now = new Date()) {
  const normalized = text.trim().replace(/\s+/g, ' ');
  if (normalized === '') {
    throw new TodoError('Todo text cannot be empty.');
  }
  const id = nextId(todos);
  // Past this point ids lose precision, and loadTodos would reject the saved file.
  if (!Number.isSafeInteger(id)) {
    throw new TodoError(`Cannot add a todo: the next id would exceed ${Number.MAX_SAFE_INTEGER}.`);
  }
  const todo = {
    id,
    text: normalized,
    completed: false,
    createdAt: now.toISOString(),
  };
  return { todos: [...todos, todo], todo };
}

/**
 * Marks a todo as done without modifying the input list. `changed` is false
 * when the todo was already done, so the caller can skip the write.
 */
function completeTodo(todos, id) {
  const todo = findTodo(todos, id);
  if (todo.completed) {
    return { todos, todo, changed: false };
  }
  const updated = { ...todo, completed: true };
  return {
    todos: todos.map((candidate) => (candidate.id === id ? updated : candidate)),
    todo: updated,
    changed: true,
  };
}

/** Returns a new list without the todo; the input list is not modified. */
function deleteTodo(todos, id) {
  const todo = findTodo(todos, id);
  return { todos: todos.filter((candidate) => candidate.id !== id), todo };
}

function formatTodos(todos) {
  if (todos.length === 0) {
    return 'No todos yet.';
  }
  const lines = todos.map((todo) => `${todo.id}. [${todo.completed ? 'x' : ' '}] ${todo.text}`);
  const done = todos.filter((todo) => todo.completed).length;
  lines.push('', `${todos.length - done} pending, ${done} done`);
  return lines.join('\n');
}

module.exports = {
  TodoError,
  addTodo,
  completeTodo,
  deleteTodo,
  formatTodos,
  parseId,
};
'use strict';

const fs = require('node:fs');
const { TodoError } = require('./todos');

const TODO_FILE_NAME = 'todos.json';

const FIELD_RULES = [
  { field: 'id', expected: 'a positive integer', isValid: (value) => Number.isSafeInteger(value) && value > 0 },
  { field: 'text', expected: 'a non-empty string', isValid: (value) => typeof value === 'string' && value.trim() !== '' },
  { field: 'completed', expected: 'a boolean', isValid: (value) => typeof value === 'boolean' },
  {
    field: 'createdAt',
    expected: 'an ISO 8601 timestamp',
    isValid: (value) => typeof value === 'string' && !Number.isNaN(Date.parse(value)),
  },
];

function corrupted(filePath, detail) {
  return new TodoError(`${filePath} is corrupted: ${detail}. Fix or remove the file and try again.`);
}

function validateTodos(data, filePath) {
  if (!Array.isArray(data)) {
    throw corrupted(filePath, 'expected a JSON array of todos');
  }
  const seenIds = new Set();
  data.forEach((todo, index) => {
    if (todo === null || typeof todo !== 'object' || Array.isArray(todo)) {
      throw corrupted(filePath, `entry ${index} is not an object`);
    }
    for (const { field, expected, isValid } of FIELD_RULES) {
      if (!isValid(todo[field])) {
        throw corrupted(filePath, `entry ${index} has an invalid "${field}" (expected ${expected})`);
      }
    }
    if (seenIds.has(todo.id)) {
      throw corrupted(filePath, `id ${todo.id} appears more than once`);
    }
    seenIds.add(todo.id);
  });
}

/** Reads and validates the todo list. A missing file is an empty list. */
function loadTodos(filePath) {
  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      return [];
    }
    throw new TodoError(`Could not read ${filePath}: ${err.message}`, { cause: err });
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw corrupted(filePath, `invalid JSON (${err.message})`);
  }
  validateTodos(data, filePath);
  return data;
}

/**
 * Writes to a temporary file and renames it over the target, so a crash or a
 * concurrent writer never leaves a half-written todos.json behind.
 */
function saveTodos(filePath, todos) {
  const tempPath = `${filePath}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tempPath, `${JSON.stringify(todos, null, 2)}\n`);
    fs.renameSync(tempPath, filePath);
  } catch (err) {
    fs.rmSync(tempPath, { force: true });
    throw new TodoError(`Could not write ${filePath}: ${err.message}`, { cause: err });
  }
}

module.exports = {
  TODO_FILE_NAME,
  loadTodos,
  saveTodos,
};
# cli-todo-app

A command-line todo list. Todos are stored in `todos.json` in the directory you run the command from. It has no runtime dependencies and needs Node.js 20 or newer.

## Usage

```sh
node index.js add "Buy groceries"   # Added todo 1: Buy groceries
node index.js list
node index.js complete 1            # Completed todo 1: Buy groceries
node index.js delete 1              # Deleted todo 1: Buy groceries
node index.js help
```

`list` prints one line per todo, then a count:

```
1. [x] Buy groceries
2. [ ] Walk the dog

1 pending, 1 done
```

Errors go to stderr and the command exits with status 1. Output from successful commands goes to stdout with exit status 0.

## Storage

`todos.json` is a JSON array:

```json
[
  { "id": 1, "text": "Buy groceries", "completed": false, "createdAt": "2026-01-02T03:04:05.000Z" }
]
```

If the file is missing, the list is empty. `list` does not create the file; the first `add` does. If the file is not valid JSON or an entry has the wrong shape, every command stops with an error that names the problem and leaves the file untouched.

## Behavior notes

- A new todo gets the highest existing id plus one. Deleting a todo in the middle never produces a duplicate id. Deleting the highest-numbered todo frees its id for the next `add`, because the file stores only the list.
- `add Buy groceries` without quotes works too: the words are joined with spaces. Leading and trailing whitespace is trimmed, and any run of whitespace, including newlines, becomes a single space so each todo stays on one line.
- Ids must be positive integers written with the digits 0-9. Values such as `1.5`, `-1`, `1e2` and `0x1` are rejected.
- Completing a todo that is already done succeeds and says so without rewriting the file.
- Each save writes a temporary file and renames it over `todos.json`, so the file is never left half-written. There is no lock, so two commands that write at the same moment can lose one of the changes.

## Development

```sh
npm install
npm test       # node:test: unit, CLI and end-to-end tests
npm run lint   # ESLint recommended rules
```
'use strict';

const { afterEach, beforeEach, describe, it } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { run, USAGE } = require('../index');

const NOW = new Date('2026-01-02T03:04:05.000Z');

let dir;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function cli(...argv) {
  return run(argv, { cwd: dir, now: NOW });
}

function todoFile() {
  return path.join(dir, 'todos.json');
}

function storedTodos() {
  return JSON.parse(fs.readFileSync(todoFile(), 'utf8'));
}

function assertFails(result, message) {
  assert.equal(result.exitCode, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, message);
}

describe('command dispatch', () => {
  it('prints usage and exits 1 when no command is given', () => {
    const result = cli();
    assertFails(result, /^Error: Missing command\./);
    assert.ok(result.stderr.endsWith(USAGE));
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage and exits 0 for "${flag}"`, () => {
      assert.deepEqual(cli(flag), { exitCode: 0, stdout: USAGE, stderr: '' });
    });
  }

  // Object.prototype names catch a regression to a plain-object command table.
  for (const command of ['remove', 'ADD', 'toString', '__proto__']) {
    it(`rejects the unknown command "${command}"`, () => {
      assertFails(cli(command), new RegExp(`^Error: Unknown command "${command}"`));
    });
  }
});

describe('add', () => {
  it('creates todos.json with the new todo', () => {
    assert.deepEqual(cli('add', 'Buy groceries'), { exitCode: 0, stdout: 'Added todo 1: Buy groceries', stderr: '' });
    assert.deepEqual(storedTodos(), [{ id: 1, text: 'Buy groceries', completed: false, createdAt: NOW.toISOString() }]);
  });

  it('joins unquoted words into one todo', () => {
    assert.equal(cli('add', 'Buy', 'groceries').stdout, 'Added todo 1: Buy groceries');
  });

  it('gives each new todo the next id', () => {
    cli('add', 'First');
    cli('add', 'Second');
    assert.deepEqual(
      storedTodos().map((todo) => todo.id),
      [1, 2],
    );
  });

  it('does not create a duplicate id after deleting a todo from the middle', () => {
    cli('add', 'One');
    cli('add', 'Two');
    cli('add', 'Three');
    cli('delete', '2');
    assert.equal(cli('add', 'Four').stdout, 'Added todo 4: Four');
    assert.deepEqual(
      storedTodos().map((todo) => todo.id),
      [1, 3, 4],
    );
  });

  it('fails without text and does not create todos.json', () => {
    assertFails(cli('add'), /Missing todo text/);
    assert.equal(fs.existsSync(todoFile()), false);
  });

  it('fails for whitespace-only text', () => {
    assertFails(cli('add', '   ', ''), /Todo text cannot be empty/);
    assert.equal(fs.existsSync(todoFile()), false);
  });
});

describe('list', () => {
  it('reports an empty list when todos.json does not exist, without creating it', () => {
    assert.deepEqual(cli('list'), { exitCode: 0, stdout: 'No todos yet.', stderr: '' });
    assert.equal(fs.existsSync(todoFile()), false);
  });

  it('reports an empty list once every todo is deleted', () => {
    cli('add', 'Temporary');
    cli('delete', '1');
    assert.equal(cli('list').stdout, 'No todos yet.');
  });

  it('shows each todo with its id, status indicator and text', () => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
    assert.equal(cli('list').stdout, ['1. [ ] Buy groceries', '2. [x] Walk the dog', '', '1 pending, 1 done'].join('\n'));
  });

  it('fails when given arguments', () => {
    assertFails(cli('list', 'all'), /list command takes no arguments/);
  });
});

describe('complete', () => {
  it('marks the todo as done and saves it', () => {
    cli('add', 'Buy groceries');
    assert.deepEqual(cli('complete', '1'), { exitCode: 0, stdout: 'Completed todo 1: Buy groceries', stderr: '' });
    assert.equal(storedTodos()[0].completed, true);
  });

  it('succeeds without rewriting the file when the todo is already done', () => {
    cli('add', 'Buy groceries');
    cli('complete', '1');
    // Saving renames a new file into place, so an unchanged inode means no write happened.
    const before = fs.statSync(todoFile()).ino;
    assert.deepEqual(cli('complete', '1'), { exitCode: 0, stdout: 'Todo 1 is already done: Buy groceries', stderr: '' });
    assert.equal(fs.statSync(todoFile()).ino, before);
  });
});

describe('delete', () => {
  it('removes the todo and keeps the others', () => {
    cli('add', 'Keep me');
    cli('add', 'Delete me');
    assert.deepEqual(cli('delete', '2'), { exitCode: 0, stdout: 'Deleted todo 2: Delete me', stderr: '' });
    assert.deepEqual(
      storedTodos().map((todo) => todo.text),
      ['Keep me'],
    );
  });

  it('fails when the todo was already deleted', () => {
    cli('add', 'Once');
    cli('delete', '1');
    assertFails(cli('delete', '1'), /No todo with id 1/);
  });
});

for (const command of ['complete', 'delete']) {
  describe(`${command} argument errors`, () => {
    beforeEach(() => {
      cli('add', 'Existing');
    });

    it('fails when the id is missing', () => {
      assertFails(cli(command), new RegExp(`Missing todo id\\. Usage: node index\\.js ${command} <id>`));
    });

    it('fails for an id that is not a positive integer', () => {
      assertFails(cli(command, 'abc'), /Invalid todo id "abc"/);
    });

    it('fails for an id that does not exist', () => {
      assertFails(cli(command, '99'), /No todo with id 99/);
    });

    it('fails when given more than one id', () => {
      assertFails(cli(command, '1', '2'), /Too many arguments/);
    });

    it('leaves todos.json unchanged after an error', () => {
      const before = fs.readFileSync(todoFile(), 'utf8');
      cli(command, '99');
      assert.equal(fs.readFileSync(todoFile(), 'utf8'), before);
    });

    it('fails with "No todo" when todos.json does not exist', () => {
      fs.rmSync(todoFile());
      assertFails(cli(command, '1'), /No todo with id 1/);
      assert.equal(fs.existsSync(todoFile()), false);
    });
  });
}

describe('corrupted todos.json', () => {
