  });

  it('exits quietly when the reader closes the pipe early, as in `list | head -1`', async () => {
    seedTodos();
    const result = await new Promise((resolve, reject) => {
      const child = spawn(process.execPath, [INDEX, 'list'], { cwd: dir, timeout: TIMEOUT_MS });
      let stderr = '';
      child.stdout.once('data', () => child.stdout.destroy());
      child.stderr.on('data', (chunk) => {
        stderr += chunk;
      });
      child.on('error', reject);
      child.on('close', (status) => resolve({ status, stderr }));
    });
    assert.deepEqual(result, { status: 0, stderr: '' });
  });

  it('never lets a reader see a half-written todos.json while other processes write', async () => {
