describe('list --pending', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('add', 'Write report');
    cli('complete', '2');
  });

  it('shows only the todos that are not completed, in the list format', () => {
    assert.deepEqual(cli('list', '--pending'), {
      exitCode: 0,
      stdout: ['1. [ ] Buy groceries', '3. [ ] Write report', '', '2 pending, 1 done'].join('\\n'),
      stderr: '',
    });
  });

  it('leaves plain list showing every todo', () => {
    assert.equal(
      cli('list').stdout,
      ['1. [ ] Buy groceries', '2. [x] Walk the dog', '3. [ ] Write report', '', '2 pending, 1 done'].join('\\n'),
    );
  });

  it('does not modify todos.json', () => {
    const before = fs.readFileSync(todoFile(), 'utf8');
    cli('list', '--pending');
    assert.equal(fs.readFileSync(todoFile(), 'utf8'), before);
  });

  it('says nothing is pending once every todo is done', () => {
    cli('complete', '1');
    cli('complete', '3');
    assert.deepEqual(cli('list', '--pending'), { exitCode: 0, stdout: 'No pending todos.\\n\\n0 pending, 3 done', stderr: '' });
  });

  it('reports an empty list when todos.json does not exist', () => {
    fs.rmSync(todoFile());
    assert.deepEqual(cli('list', '--pending'), { exitCode: 0, stdout: 'No todos yet.', stderr: '' });
  });
});

describe('edit', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('complete', '2');
  });

  it('replaces the text and saves it', () => {
    assert.deepEqual(cli('edit', '1', 'Buy oat milk'), { exitCode: 0, stdout: 'Edited todo 1: Buy oat milk', stderr: '' });
    assert.equal(storedTodos()[0].text, 'Buy oat milk');
  });

  it('keeps the id, completed status and createdAt, and leaves other todos alone', () => {
    const later = new Date('2027-05-06T07:08:09.000Z');
    const before = storedTodos();
    run(['edit', '2', 'Walk the cat'], { cwd: dir, now: later });
    assert.deepEqual(storedTodos(), [before[0], { ...before[1], text: 'Walk the cat' }]);
    assert.equal(storedTodos()[1].completed, true);
    assert.equal(storedTodos()[1].createdAt, NOW.toISOString());
  });

  it('joins unquoted words and collapses whitespace like add', () => {
    assert.equal(cli('edit', '1', 'Buy', '  oat\\n milk ').stdout, 'Edited todo 1: Buy oat milk');
    assert.equal(storedTodos()[0].text, 'Buy oat milk');
  });

  it('shows the new text in list', () => {
    cli('edit', '1', 'Buy oat milk');
    assert.match(cli('list').stdout, /^1\\. \\[ \\] Buy oat milk$/m);
  });

  describe('errors', () => {
    let before;

    beforeEach(() => {
      before = fs.readFileSync(todoFile(), 'utf8');
    });

    afterEach(() => {
      assert.equal(fs.readFileSync(todoFile(), 'utf8'), before);
    });

    it('fails when the id is missing', () => {
      assertFails(cli('edit'), /Missing todo id\\. Usage: node index\\.js edit <id>/);
    });

    it('fails when the text is missing', () => {
      assertFails(cli('edit', '1'), /Missing todo text/);
    });

    it('fails when the text is empty or whitespace only', () => {
      assertFails(cli('edit', '1', ''), /Todo text cannot be empty/);
      assertFails(cli('edit', '1', '   ', ' '), /Todo text cannot be empty/);
    });

    it('fails for an id that is not a positive integer', () => {
      assertFails(cli('edit', 'abc', 'New text'), /Invalid todo id "abc"/);
      assertFails(cli('edit', '0', 'New text'), /Invalid todo id "0"/);
    });

    it('fails for an id that does not exist', () => {
      assertFails(cli('edit', '99', 'New text'), /No todo with id 99/);
    });
  });

  it('fails with "No todo" when todos.json does not exist, without creating it', () => {
    fs.rmSync(todoFile());
    assertFails(cli('edit', '1', 'New text'), /No todo with id 1/);
    assert.equal(fs.existsSync(todoFile()), false);
  });
});
