describe('list --pending', () => {
  beforeEach(() => {
    cli('add', 'Buy groceries');
    cli('add', 'Walk the dog');
    cli('add', 'Write report');
    cli('complete', '2');
  });

  it('shows only the todos that are not completed, in the list format', () => {
    assert.deepEqual(cli('list', '--pending'), {
      exitCode: 0,
      stdout: ['1. [ ] Buy groceries', '3. [ ] Write report', '', '2 pending, 1 done'].join('\\n'),
      stderr: '',
    });
  });

  it('leaves plain list showing every todo', () => {
    assert.equal(
      cli('list').stdout,
      ['1. [ ] Buy groceries', '2. [x] Walk the dog', '3. [ ] Write report', '', '2 pending, 1 done'].join('\\n'),
    );
  });

  it('does not modify todos.json', () => {
    const before = fs.readFileSync(todoFile(), 'utf8');
    cli('list', '--pending');
    assert.equal(fs.readFileSync(todoFile(), 'utf8'), before);
  });

  it('says nothing is pending once every todo is done', () => {
    cli('complete', '1');
    cli('complete', '3');
    assert.deepEqual(cli('list', '--pending'), { exitCode: 0, stdout: 'No pending todos.\\n\\n0 pending, 3 done', stderr: '' });
  });

  it('reports an empty list when todos.json does not exist', () => {
